select status, case when status in ('SHIPPED', 'CANCELLED') then 'tier_1' else 'other' end status_group, sum(case when channel = 'mobile' then shipping_fee else 0 end) mobile_shipping_fee, max(order_date) latest_order_date, sum(amount) total_amount from orders where customer_id is null or discount between 0.27 and 0.36 group by status, case when status in ('SHIPPED', 'CANCELLED') then 'tier_1' else 'other' end order by latest_order_date;
